const IKO_TEMPS_ESTIME = { 'IKO-E05': 0.073, 'IKO-H03': 0.045, 'IKO-F02': 0.291, 'IKO-G01': 0.051, 'IKO-R04': 0.5, 'IKO-R05': 0.6, 'IKO-R06': 0.15 };
IKO_COMPLEXES.forEach(c => {
  const iso = c.couches.some(k => /^(ISO-|HI-01|HI-02)/.test(k[0])), lourd = [1, 3, 5, 6].includes(c.cat);
  const sec = c.cat === 8 ? (c.u === 'ml' ? 5 : 6) : lourd ? (iso ? 10 : 8) : (iso ? 9 : 7);
  const fam = { 5: 13, 6: 19, 7: 20, 8: 21, 9: 22, 10: 23 }[sec];
  const eq = c.cad ? CAD_OUVRAGES.find(o => o[CAD_I.REF] === c.cad && o[CAD_I.U] === c.u) : null;
  const h = eq ? eq[CAD_I.H] : IKO_TEMPS_ESTIME[c.ref] || 0;
  const desc = 'Procédé ' + c.proc + ' · ' + c.usage + ' · support ' + c.sup + '. Temps : ' + (eq ? 'ouvrage SMAC ' + eq[CAD_I.REF] : 'EXP. à confirmer') + '.';
  CAD_OUVRAGES.push([c.ref, sec, fam, c.nom, desc, c.sup, c.u, h]);
  CAD_COMPO[c.ref] = c.couches;
});

